  @echo two {{x}}

[parallel]
top: (one `echo a >&2; echo a`) (two `exit 3`)
one x:
  @echo one {{x}}
two x:
  @echo two {{x}}

foo: (bar `echo arg >&2; echo arg`)
  @echo foo
bar x:
  @echo bar {{x}}

foo: && (bar `echo arg >&2; echo arg`)
  @echo foo
bar x:
  @echo bar {{x}}

top: one (one 'x') one
one a=`echo d >&2; echo d`:
  @echo {{a}}

a := `read A && echo $A`
b := `read B && echo $B`
foo:
  @echo {{a}} {{b}}

set no-cd
x := `ls | tr '\n' ' '`
foo:
  @ls | tr '\n' ' '
  @echo {{x}}
